SELECT 
FROM qa_answer a
INNER JOIN qa_conversation c ON c.public_id = a.conversation_id
WHERE a.owner_id = #{ownerId}
  AND a.idempotency_key = #{idempotencyKey}
  AND c.deleted_at IS NULL

SELECT 
FROM qa_answer a
INNER JOIN qa_conversation c ON c.public_id = a.conversation_id
WHERE a.public_id = #{id}
  AND c.owner_id = #{ownerId}
  AND c.deleted_at IS NULL

mapper.update:
UPDATE qa_answer
SET status = #{status}
WHERE public_id = #{id}
  AND status IN ('PENDING', 'RETRIEVING', 'QUERYING', 'GENERATING')

UPDATE qa_answer
SET app_conversation_id = #{appConversationId}
WHERE public_id = #{id}
  AND status IN ('GENERATING', 'CANCEL_REQUESTED')
  AND (app_conversation_id IS NULL OR app_conversation_id = #{appConversationId})

UPDATE qa_answer
SET content = #{content}
WHERE public_id = #{id}
  AND status = 'GENERATING'
